+  function listener() {
+    detach();
+    abort(request, signal.reason);
+  }
+  function detach() {
+    request.detachAbortSignal = null;
+    signal.removeEventListener('abort', listener);
+  }
+  request.detachAbortSignal = detach;
+  signal.addEventListener('abort', listener);

